CREATE TABLE IF NOT EXISTS evidence_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, entity_type TEXT NOT NULL, entity_id UUID NOT NULL, type TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'self_reported', label TEXT NOT NULL, value TEXT, media_url TEXT, verified_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
CREATE INDEX idx_evidence_entity ON evidence_items(tenant_id, entity_type, entity_id);
CREATE TABLE IF NOT EXISTS evidence_display_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, entity_type TEXT NOT NULL, evidence_type TEXT NOT NULL, position INTEGER DEFAULT 0, show_level BOOLEAN DEFAULT TRUE, show_date BOOLEAN DEFAULT TRUE, required BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
